#!/usr/bin/env python3
from __future__ import annotations

import argparse
import re
import subprocess
from pathlib import Path

ALLOWED_TYPES = {
    "feat",
    "fix",
    "perf",
    "docs",
    "ci",
    "test",
    "refactor",
    "chore",
    "release",
}
SUBJECT_RE = re.compile(r"^(?P<kind>[a-z]+)(?:\([^)]+\))?!?:\s+\S")
# Subjects generated by git itself, never typed by an author:
# `git merge` / `gh pr merge --merge` default to "Merge branch '...'",
# "Merge pull request #NN from ...", "Merge remote-tracking branch '...' ...",
# "Merge commit '...'", "Merge tag '...'"; `git revert` defaults to
# `Revert "<subject>"`; and reverting a revert defaults to
# `Reapply "<subject>"`. Repeated reverts alternate between those two forms
# (`Revert "Reapply "..."` and so on), so the two prefixes cover every
# generation of a revert chain. No conventional type can start with these
# prefixes, so a hand-typed non-conventional subject still fails: the
# exemption only covers subjects that are a verbatim git-generated form (#83).
#
# It applies to every subject source in main(), the bare-subject arguments
# (the PR-title gate) included. That is deliberate rather than an oversight: a
# PR that reverts work is routinely titled `Revert "<subject>"`, and failing it
# would reintroduce the very false positive this fixes. The consequence is that
# a PR title which happens to be one of these forms passes the gate; anything
# else author-typed does not.
EXEMPT_SUBJECT_PREFIXES = ("Merge ", 'Revert "', 'Reapply "')


def exempt_subject(subject: str) -> bool:
    return subject.startswith(EXEMPT_SUBJECT_PREFIXES)


def git_subjects(rev_range: str) -> list[str]:
    output = subprocess.check_output(
        ["git", "log", "--pretty=format:%s", rev_range], text=True
    ).strip()
    return [line.strip() for line in output.splitlines() if line.strip()]


def valid_subject(subject: str) -> bool:
    match = SUBJECT_RE.match(subject)
    return bool(match and match.group("kind") in ALLOWED_TYPES)


def commit_message_subject(path: Path) -> str | None:
    for line in path.read_text(encoding="utf-8").splitlines():
        subject = line.strip()
        if subject and not subject.startswith("#"):
            return subject
    return None


def main() -> int:
    parser = argparse.ArgumentParser(description="Validate conventional commit subjects")
    parser.add_argument("subjects", nargs="*")
    parser.add_argument("--range", dest="rev_range")
    parser.add_argument("--message-file")
    args = parser.parse_args()

    subjects = list(args.subjects)
    if args.rev_range:
        subjects.extend(git_subjects(args.rev_range))
    if args.message_file:
        subject = commit_message_subject(Path(args.message_file))
        if subject:
            subjects.append(subject)

    invalid = [
        subject
        for subject in subjects
        if not valid_subject(subject) and not exempt_subject(subject)
    ]
    if invalid:
        print("invalid commit subject(s):")
        for subject in invalid:
            print(f"  {subject}")
        print(
            "commit subjects must use conventional commits because preview notes are generated from them."
        )
        print("example: fix(update): install selected channel")
        print("expected: type(optional-scope): subject")
        print("allowed types: " + ", ".join(sorted(ALLOWED_TYPES)))
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
